words = text.split(" ")
last = len(words) - 1
result = []
for index, word in enumerate(words):
    if any(ch.isupper() for ch in word[1:]):
        result.append(word)
    elif (0 < index < last
          and word.rstrip(_TRAILING_PUNCTUATION).lower() in SMALL_WORDS):
